/**
 * Lấy hồ sơ đặc tính và nguồn gốc Wikipedia chi tiết cho nguyên tố theo số hiệu Z
 */
export function getElementDossier(atomicNumber: number): ElementDossier | undefined {
  return ELEMENT_DOSSIERS[atomicNumber];
}
